用户的原始要求（硬性）：
- 为 Windows 版「光标朗读」做 Android 版，功能对齐 Windows v0.5（光标/选中文字朗读、开始/暂停/继续/停止、TTS 引擎和语音设置、音色包导入+试听、标点停顿、语速、多音字前端+用户词库）。
- Android 上无法实现的用最接近的系统方式替代（无障碍服务读取选中/焦点文字、悬浮按钮、分享菜单朗读）。
- 完全离线、体积小、低端手机（4GB 内存、2 核也要能流畅）、黑白灰日式极简界面；最低 Android 6（API 23）。
- 用户是编程初学者、眼睛不好：操作要少、结果一次说清。


只审下面无障碍服务/取文字/悬浮条/快捷键代码。请严格审查，不要附和我也不要附和用户；按严重程度编号，写出位置、原因、改法；不确定的标“推测”。中文，800 字以内，务必写完整。

<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    package="app.caretreader.tts">

    <uses-sdk android:minSdkVersion="23" android:targetSdkVersion="36" />

    <!-- 完全离线：没有 INTERNET。只申请朗读时在后台继续播放所需的权限。 -->
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />

    <application
        android:name="app.caretreader.tts.App"
        android:label="@string/app_name"
        android:icon="@mipmap/ic_launcher"
        android:allowBackup="false"
        android:largeHeap="true"
        android:extractNativeLibs="false"
        android:supportsRtl="false"
        android:theme="@style/AppTheme">

        <activity
            android:name="app.caretreader.tts.SettingsActivity"
            android:exported="true"
            android:launchMode="singleTask"
            android:label="@string/app_name">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
            <intent-filter>
                <action android:name="android.speech.tts.engine.CONFIGURE_ENGINE" />
                <category android:name="android.intent.category.DEFAULT" />
            </intent-filter>
        </activity>

        <!-- 选中文字菜单里的「光标朗读」+ 分享给「光标朗读」 -->
        <activity
            android:name="app.caretreader.tts.ReadTextActivity"
            android:exported="true"
            android:label="@string/read_action"
            android:excludeFromRecents="true"
            android:noHistory="true"
            android:taskAffinity=""
            android:theme="@android:style/Theme.Translucent.NoTitleBar">
            <intent-filter>
                <action android:name="android.intent.action.PROCESS_TEXT" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="text/plain" />
            </intent-filter>
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="text/plain" />
            </intent-filter>
        </activity>

        <activity
            android:name="app.caretreader.tts.CheckVoiceData"
            android:exported="true"
            android:theme="@android:style/Theme.Translucent.NoTitleBar">
            <intent-filter>
                <action android:name="android.speech.tts.engine.CHECK_TTS_DATA" />
                <category android:name="android.intent.category.DEFAULT" />
            </intent-filter>
        </activity>

        <activity
            android:name="app.caretreader.tts.GetSampleText"
            android:exported="true"
            android:theme="@android:style/Theme.Translucent.NoTitleBar">
            <intent-filter>
                <action android:name="android.speech.tts.engine.GET_SAMPLE_TEXT" />
                <category android:name="android.intent.category.DEFAULT" />
            </intent-filter>
        </activity>

        <service
            android:name="app.caretreader.tts.CaretTtsService"
            android:exported="true"
            android:label="@string/app_name">
            <intent-filter>
                <action android:name="android.intent.action.TTS_SERVICE" />
                <category android:name="android.intent.category.DEFAULT" />
            </intent-filter>
            <meta-data
                android:name="android.speech.tts"
                android:resource="@xml/tts_engine" />
        </service>

        <service
            android:name="app.caretreader.tts.ReaderService"
            android:exported="false"
            android:foregroundServiceType="mediaPlayback" />

        <service
            android:name="app.caretreader.tts.CaretAccessibilityService"
            android:exported="true"
            android:label="@string/a11y_label"
            android:permission="android.permission.BIND_ACCESSIBILITY_SERVICE">
            <intent-filter>
                <action android:name="android.accessibilityservice.AccessibilityService" />
            </intent-filter>
            <meta-data
                android:name="android.accessibilityservice"
                android:resource="@xml/accessibility_service" />
        </service>
    </application>
</manifest>

